export function applyTransaction(source,edits){
  if(typeof source!=='string'||!Array.isArray(edits))throw Error('invalid transaction');
  const sorted=[];
  for(const edit of edits){
    checkEdit(source,edit);
    sorted.push({start:edit.start,end:edit.end,after:edit.after});
  }
  sorted.sort((a,b)=>a.start-b.start||a.end-b.end);
  for(let i=1;i<sorted.length;i++){
    const previous=sorted[i-1],current=sorted[i];
    // Equality is allowed only for two adjacent nonempty ranges.
    if(current.start<previous.end ||
      (current.start===previous.end &&
        (previous.start===previous.end||current.start===current.end))){
      throw Error('conflicting edits');
    }
  }
  const parts=[];
  let cursor=0;
  for(const edit of sorted){
    parts.push(source.slice(cursor,edit.start),edit.after);
    cursor=edit.end;
  }
  parts.push(source.slice(cursor));
  return {text:parts.join(''),applied:sorted.length};
}

import {readFileSync} from 'node:fs';
import {resolve} from 'node:path';
import {pathToFileURL} from 'node:url';

// Importing the module must not consume arguments or emit output.
if(process.argv[1] && import.meta.url===pathToFileURL(resolve(process.argv[1])).href){
