import test from 'node:test';
import assert from 'node:assert/strict';
import {mkdtempSync, writeFileSync, rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {fileURLToPath} from 'node:url';
import {spawnSync} from 'node:child_process';
import {applyEdit, applyTransaction} from '../patch-transaction.js';

const edit=(start,end,before,after)=>({start,end,before,after});
const cli=fileURLToPath(new URL('../patch-transaction.js',import.meta.url));

test('validation rejects invalid types, offsets and preimages',()=>{
  for(const source of [null,undefined,42,{},['abc']]){
    assert.throws(()=>applyTransaction(source,[]),Error);
  }
  for(const edits of [null,undefined,{},'']){
    assert.throws(()=>applyTransaction('abc',edits),Error);
  }
  const invalid=[null,[],42,'x',{},
    edit(-1,1,'','x'),edit(2,1,'','x'),edit(0,4,'abc','x'),
    edit(0.5,1,'','x'),edit(0,NaN,'','x'),edit(0,Infinity,'','x'),
    edit(0,Number.MAX_SAFE_INTEGER+1,'','x'),edit('0',1,'a','x'),
    edit(0,1,null,'x'),edit(0,1,'a',4),edit(0,1,'b','x'),
    edit(1,1,'b','x')];
  for(const value of invalid){
    assert.throws(()=>applyTransaction('abc',[value]),Error);
    assert.throws(()=>applyEdit('abc',value),Error);
  }
  assert.throws(()=>applyTransaction('abc',Array(1)),Error);
  assert.throws(()=>applyTransaction('abc',[edit(0,1,'a','x'),edit(2,3,'wrong','y')]),Error);
});

test('all conflicts are rejected in either input order, including no-ops',()=>{
  const source='abcdef';
  const pairs=[
    [edit(0,3,'abc',''),edit(2,4,'cd','x')],
    [edit(0,6,'abcdef',''),edit(1,2,'b','x')],
    [edit(1,3,'bc','bc'),edit(1,3,'bc','bc')],
    [edit(2,2,'',''),edit(2,2,'','x')],
    ...[1,2,3].map(p=>[edit(1,3,'bc','x'),edit(p,p,'','')])
  ];
  for(const pair of pairs){
    assert.throws(()=>applyTransaction(source,pair),Error);
    assert.throws(()=>applyTransaction(source,[...pair].reverse()),Error);
  }
});

test('simultaneous edits preserve UTF-16, formatting, inputs and no-ops',()=>{
  const source='\ud83d\ude00\r\n a\t';
  const edits=Object.freeze([
    Object.freeze({...edit(5,6,'a','LONG'),ignored:true}),
    Object.freeze(edit(1,2,'\ude00','!')),
    Object.freeze(edit(3,3,'',''))
  ]);
  assert.deepEqual(applyTransaction(source,edits),{text:'\ud83d!\r\n LONG\t',applied:3});
  assert.deepEqual(applyTransaction(source,[...edits].reverse()),applyTransaction(source,edits));
  assert.deepEqual(edits.map(e=>e.start),[5,1,3]);
  assert.deepEqual(applyTransaction('abcd',[
    edit(4,4,'','!'),edit(1,2,'b','b'),edit(0,0,'','>')
  ]),{text:'>abcd!',applied:3});
  for(const text of ['', 'a', 'a\n', 'a\r\n', ' \t\r\n']){
    assert.deepEqual(applyTransaction(text,[]),{text,applied:0});
  }
});

test('CLI success, failures and import have exact stream/exit behavior',()=>{
  const dir=mkdtempSync(join(tmpdir(),'patch-transaction-'));
  const input=join(dir,'input.json');
  const run=args=>spawnSync(process.execPath,[cli,...args],{encoding:'utf8'});
  const failure=args=>{
    const result=run(args);
    assert.ifError(result.error);
    assert.equal(result.status,2);
    assert.equal(result.stdout,'');
    assert.ok(result.stderr.trim().length>0);
  };
  try{
    writeFileSync(input,JSON.stringify({source:'a\r\n',edits:[edit(0,1,'a','😀')],extra:true}));
    const result=run([input]);
    assert.ifError(result.error);
    assert.equal(result.status,0);
    assert.equal(result.stderr,'');
    assert.equal(result.stdout,JSON.stringify({text:'😀\r\n',applied:1})+'\n');
    failure([]);
    failure([input,input]);
    failure([join(dir,'missing.json')]);
    failure([dir]);
    for(const value of ['{','null','[]','{}',
      JSON.stringify({source:42,edits:[]}),
      JSON.stringify({source:'abc',edits:[edit(0,1,'z','x')]}),
      JSON.stringify({source:'abc',edits:[edit(0,1,'a','x'),edit(1,1,'','y')]})]){
      writeFileSync(input,value);
      failure([input]);
    }
    const imported=spawnSync(process.execPath,['--input-type=module','-e',
      `await import(${JSON.stringify(new URL('../patch-transaction.js',import.meta.url).href)})`],{encoding:'utf8'});
    assert.ifError(imported.error);
    assert.equal(imported.status,0);
    assert.equal(imported.stdout,'');
    assert.equal(imported.stderr,'');
  }finally{
    rmSync(dir,{recursive:true,force:true});
  }
});

